const fs=require('node:fs'),path=require('node:path');
const {pathToFileURL}=require('node:url');
const {chromium}=require('./qa-run/node_modules/playwright');
const original=path.join(process.cwd(),'templates/7th-grade/wayfinder-master.html');
const testFile=path.join(process.cwd(),'Tech/__qa-master-runtime.html');
const out=path.join(process.cwd(),'.github/master-qa-last-run.json');
fs.copyFileSync(original,testFile);
const issues=[],checks=[];
async function run(){
 const browser=await chromium.launch({headless:true,args:['--no-sandbox','--allow-file-access-from-files']});
 const page=await browser.newPage({viewport:{width:1280,height:800}});
 page.on('pageerror',e=>issues.push('JS '+e.message));
 await page.goto(pathToFileURL(testFile).href,{waitUntil:'domcontentloaded'});
 await page.waitForTimeout(250);
 const assert=(value,label)=>{checks.push({label,pass:!!value});if(!value)issues.push(label);};
 assert(await page.locator('#temperature .temp-priority').isVisible(),'priority TEKS permanently visible');
 assert((await page.locator('#temperature details').count())===0,'Temperature has no collapsing TEKS/details');
 assert((await page.locator('#temperatureArt').count())===0,'Temperature artwork absent');
 assert((await page.locator('#temperature [required]#temperatureFeedback').count())===1,'feedback required attribute');
 assert(!/optional/i.test(await page.locator('#temperature').innerText()),'no optional label in Temperature');
 assert((await page.locator('input[name="tempConfidence"]').count())===3,'three confidence controls');
 assert(await page.locator('#sideNav').isVisible(),'sidebar visible');
 await page.locator('#navToggle').click();assert((await page.locator('#navToggle').getAttribute('aria-expanded'))==='false','sidebar collapses');await page.locator('#navToggle').click();
 await page.evaluate(()=>{
  for(const key of ['warm','q1','q2','temp','labs'])WAYFINDER_CONFIG.destinations[key]='https://docs.google.com/forms/d/e/TEST/viewform?usp=pp_url&entry.1954781253='+key;
  document.execCommand=()=>false;
 });
 await page.locator('#warmAnswer').fill('The example helps me identify a decision.');
 await page.locator('button.copy[data-submission="warm"]').click();
 assert((await page.locator('#warmStatus .manual-copy-fallback').count())===1,'Warm-Up no-permission manual fallback');
 assert((await page.locator('#warmStatus a[href*="docs.google.com/forms"]').count())===1,'Warm-Up direct Form fallback');
 await page.locator('button.copy[data-submission="temp"]').click();
 assert((await page.locator('#tempStatus').innerText()).includes('confidence'),'blank confidence rejected');
 await page.locator('input[name="tempConfidence"]').first().check();
 await page.locator('button.copy[data-submission="temp"]').click();
 assert((await page.locator('#tempStatus').innerText()).includes('Write one'),'blank feedback rejected');
 await page.locator('#temperatureFeedback').fill('The named example helped me understand.');
 await page.locator('button.copy[data-submission="temp"]').click();
 assert((await page.locator('#tempStatus .manual-copy-fallback').count())===1,'Temperature manual copy shows exact response');
 assert((await page.locator('#tempStatus a[href*="docs.google.com/forms"]').count())===1,'Temperature direct Form fallback');
 await page.locator('[data-assembler="one"]').evaluate(el=>{
   el.innerHTML='<div data-answer-part data-type="true-false-why"><label><input type="radio" name="qa" value="false" data-phrase="The statement is false" checked>False</label><textarea data-open-response>Because the evidence shows an alternative.</textarea></div>';
 });
 await page.locator('button.create-response[data-question="one"]').click();await page.waitForTimeout(750);
 assert(await page.locator('#q1assembled').isVisible(),'mastery response assembles');
 await page.locator('button.finalize-response[data-question="one"]').click();await page.waitForTimeout(50);
 assert((await page.locator('#q1Status .manual-copy-fallback').count())===1,'mastery manual copy fallback');
 assert((await page.locator('#q1Status a[href*="docs.google.com/forms"]').count())===1,'mastery direct Form fallback');
 const checksBoxes=page.locator('.gate-check');for(let i=0;i<await checksBoxes.count();i++)await checksBoxes.nth(i).check();
 assert(await page.locator('#creativeLabs').isVisible(),'Creative Studio unlocks with four checks');
 await page.locator('#studioEvidence').fill('I compared a small change and tested the result.');
 await page.locator('#labCopy').click();
 assert((await page.locator('#labStatus .manual-copy-fallback').count())===1,'Studio manual copy fallback');
 assert((await page.locator('#labStatus a[href*="docs.google.com/forms"]').count())===1,'Studio direct Form fallback');
 await page.locator('.gate-check').first().uncheck();
 assert(!(await page.locator('#creativeLabs').isVisible()),'Studio relocks if a check is cleared');
 await page.setViewportSize({width:390,height:844});
 await page.waitForTimeout(100);
 assert((await page.locator('#temperature .temp-priority').isVisible()),'TEKS visible at phone width');
 const overflow=await page.evaluate(()=>document.documentElement.scrollWidth-window.innerWidth);
 assert(overflow<=2,'phone horizontal overflow '+overflow);
 await page.screenshot({path:path.join(process.cwd(),'.github/master-qa-mobile.png'),fullPage:true});
 await browser.close();
}
run().then(()=>{fs.writeFileSync(out,JSON.stringify({status:issues.length?'FAIL':'PASS',checks,issues},null,2));console.log(JSON.stringify({status:issues.length?'FAIL':'PASS',checks:checks.length,issues}));if(issues.length)process.exitCode=1;}).catch(e=>{const msg=String(e).slice(0,800);fs.writeFileSync(out,JSON.stringify({status:'ERROR',issues:[msg],checks},null,2));console.error(msg);process.exitCode=1;});
